                    << ", Site: freelist_getReg, mode=mark_free, class=int"
                    << " — NO valid allocated target (skipped, no UB)."
                    << std::endl;
            }
            return false;
        }
        PhysRegIdPtr target_reg = o3cpu->physRegFile().intPhysRegId(target);

            PhysRegIdPtr target_reg = o3cpu->physRegFile().intPhysRegId(target);
            o3cpu->physFreeList().addReg(target_reg);  // re-add allocated
